import os
import pytest
from envcfg import load_config, ConfigError


def test_precedence():
    """Test that values are overridden in the correct order."""
    defaults = {
        "server": {
            "port": 8080,
            "host": "localhost"
        }
    }

    # Test TOML overrides defaults
    with open("test_config.toml", "w") as f:
        f.write("[server]\nport = 9090\n")

    config = load_config(
        defaults=defaults,
        toml_path="test_config.toml",
        env_prefix="TEST"
    )
    assert config["server"]["port"] == 9090
    assert config["server"]["host"] == "localhost"
    os.remove("test_config.toml")


def test_env_overrides():
    """Test that environment variables override both defaults and TOML."""
    defaults = {
        "server": {
            "port": 8080,
            "host": "localhost"
        }
    }

    # Test environment overrides
    env = {"TEST__SERVER__PORT": "8081"}
    config = load_config(
        defaults=defaults,
        toml_path=None,
        env_prefix="TEST",
        env_dict=env
    )
    assert config["server"]["port"] == 8081
    assert config["server"]["host"] == "localhost"


def test_nested_overrides():
    """Test nested key overrides."""
    defaults = {
        "database": {
            "credentials": {
                "user": "guest",
                "password": "pass"
            }
        }
    }

    env = {"TEST__DATABASE__CREDENTIALS__USER": "admin"}
    config = load_config(
        defaults=defaults,
        toml_path=None,
        env_prefix="TEST",
        env_dict=env
    )
    assert config["database"]["credentials"]["user"] == "admin"
    assert config["database"]["credentials"]["password"] == "pass"


